LoanProduct Loan::getLoanProduct(const DbClientPtr &clientPtr) const {
    static const std::string sql = "select * from loan_product where id = $1";
    Result r(nullptr);
    {
        auto binder = *clientPtr << sql;
        binder << *productId_ << Mode::Blocking >>
            [&r](const Result &result) { r = result; };
        binder.exec();
    }
    if (r.size() == 0)
    {
        throw UnexpectedRows("0 rows found");
    }
    else if (r.size() > 1)
    {
        throw UnexpectedRows("Found more than one row");
    }
    return LoanProduct(r[0]);
}

void Loan::getLoanProduct(const DbClientPtr &clientPtr,
                          const std::function<void(LoanProduct)> &rcb,
                          const ExceptionCallback &ecb) const
{
    static const std::string sql = "select * from loan_product where id = $1";
    *clientPtr << sql
               << *productId_
               >> [rcb = std::move(rcb), ecb](const Result &r){
                    if (r.size() == 0)
                    {
                        ecb(UnexpectedRows("0 rows found"));
                    }
                    else if (r.size() > 1)
                    {
                        ecb(UnexpectedRows("Found more than one row"));
                    }
                    else
                    {
                        rcb(LoanProduct(r[0]));
                    }
               }
               >> ecb;
}
Loan Loan::getLoan(const DbClientPtr &clientPtr) const {
    static const std::string sql = "select * from loan where id = $1";
    Result r(nullptr);
    {
        auto binder = *clientPtr << sql;
        binder << *glimParentLoanId_ << Mode::Blocking >>
            [&r](const Result &result) { r = result; };
        binder.exec();
    }
    if (r.size() == 0)
    {
        throw UnexpectedRows("0 rows found");
    }
    else if (r.size() > 1)
    {
        throw UnexpectedRows("Found more than one row");
    }
    return Loan(r[0]);
}

void Loan::getLoan(const DbClientPtr &clientPtr,
                   const std::function<void(Loan)> &rcb,
                   const ExceptionCallback &ecb) const
{
    static const std::string sql = "select * from loan where id = $1";
    *clientPtr << sql
               << *glimParentLoanId_
               >> [rcb = std::move(rcb), ecb](const Result &r){
                    if (r.size() == 0)
                    {
                        ecb(UnexpectedRows("0 rows found"));
                    }
                    else if (r.size() > 1)
                    {
                        ecb(UnexpectedRows("Found more than one row"));
                    }
                    else
                    {
                        rcb(Loan(r[0]));
                    }
               }
               >> ecb;
}
